@pytest.mark.parametrize("method,endpoint", [("GET", ENDPOINT)])
def test_realtime_current_weather_table_driven(
    api_client,
    valid_api_key: str,
    schema_validator: SwaggerSchemaValidator,
    request_schema: Dict[str, Any],
    response_schema_200: Dict[str, Any],
    response_schema_error: Dict[str, Any],
    test_data: List[Dict[str, Any]],
    retry_settings: Tuple[int, float],
):
    """
    Table-driven test for GET /v1/current.json.
    - Iterates through all objects in current.json.json
    - Validates the request against the request schema before sending
    - Sends the request using api_client fixture
    - Validates the response against the appropriate response schema
    - Asserts returned status codes match expectations
    - Uses configurable retry behavior from config.yml (optional)
    """
    if not valid_api_key:
        pytest.skip("Valid API key is required for these tests. Authentication variations are tested separately.")

    retries, backoff = retry_settings

    # Iterate through each test case in the JSON array
    for idx, entry in enumerate(test_data):
        scenario_name = str(entry.get("scenario", f"scenario_{idx}"))
        expected_status = int(entry.get("statusCode", 200))

        # Build params from JSON entry and add API key
        params = build_query_params(entry, valid_api_key)

        # Validate request params with schema before sending
        schema_validator.validate_with_schema(params, request_schema)

        # Simple retry mechanism for transient failures
        attempt = 0
        last_exc: Exception = None
        response = None

        while attempt <= retries:
            try:
                response = api_client.get(endpoint=ENDPOINT, params=params)
                break
            except Exception as e:
                last_exc = e
                if attempt == retries:
                    raise
                time.sleep(backoff)
                attempt += 1

        assert response is not None, f"No response received for '{scenario_name}'"
        assert response.status_code == expected_status, (
            f"[{scenario_name}] Expected HTTP {expected_status}, got {response.status_code}"
        )

        # Ensure JSON response body can be decoded when present
        body: Dict[str, Any] = {}
        content_type = response.headers.get("Content-Type", "")
        # Validate response JSON if content-type indicates JSON or if body is parseable JSON
        if "application/json" in content_type.lower() or (response.text or "").strip().startswith(("{", "[")):
            try:
                body = response.json()
            except ValueError:
                pytest.fail(f"[{scenario_name}] Response body is not valid JSON for Content-Type '{content_type}'")

            # Validate response schema using the validator
            if response.status_code == 200:
                schema_validator.validate_with_schema(body, response_schema_200)
            elif response.status_code in (400, 401, 403):
                schema_validator.validate_with_schema(body, response_schema_error)
            else:
                # If an unexpected status code is returned, still try to validate as error schema
                schema_validator.validate_with_schema(body, response_schema_error)
        else:
            # For non-JSON content, assert empty or unexpected when success expected
            if expected_status == 200:
                pytest.fail(f"[{scenario_name}] Expected JSON response for 200 but got Content-Type '{content_type}'")


